import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { Area, AreaChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { toast } from 'sonner'
import { ArrowDownRight, ArrowRight, ArrowUpRight, Bell, Box, Check, ChevronDown, ChevronLeft, ChevronRight, CircleDollarSign, ClipboardList, Download, Edit3, Eye, FileClock, ImagePlus, LayoutDashboard, Loader2, LogOut, Menu, Moon, PackageCheck, PanelLeftClose, PanelLeftOpen, Plus, RefreshCw, Search, Settings as SettingsIcon, ShieldCheck, ShoppingBag, Sparkles, Sun, Truck, Upload, Users, WalletCards, X } from 'lucide-react'
import { supabase } from '@/lib/supabase'
import { convertPrice, dateFr, money, orderTotal, shortMoney, slugify } from './lib/commerce'
import { nextStatuses, paymentLabels, statusLabels, type Audit, type Category, type Currency, type ExchangeRate, type Notification, type Order, type PaymentStatus, type Product, type Settings, type Staff, type Status, type Zone } from './types'
import './admin.css'

type Page = 'overview'|'products'|'orders'|'pricing'|'shipping'|'customers'|'notifications'|'team'|'settings'
type Session = { user:{id:string;email?:string} } | null
type Data = { products:Product[];categories:Category[];orders:Order[];zones:Zone[];notifications:Notification[];staff:Staff[];settings:Settings[];rates:ExchangeRate[];audit:Audit[] }
const emptyData:Data={products:[],categories:[],orders:[],zones:[],notifications:[],staff:[],settings:[],rates:[],audit:[]}
const nav:{id:Page;label:string;icon:typeof LayoutDashboard;permission?:string}[]=[
  {id:'overview',label:'Vue d’ensemble',icon:LayoutDashboard}, {id:'products',label:'Produits',icon:Box,permission:'products.read'},
  {id:'orders',label:'Commandes',icon:ClipboardList,permission:'orders.read'}, {id:'pricing',label:'Prix et devises',icon:CircleDollarSign,permission:'products.read'},
  {id:'shipping',label:'Livraison et zones',icon:Truck,permission:'orders.read'}, {id:'customers',label:'Clients',icon:Users,permission:'orders.read'},
  {id:'notifications',label:'Notifications',icon:Bell,permission:'orders.read'}, {id:'team',label:'Équipe et accès',icon:ShieldCheck,permission:'staff.write'},
  {id:'settings',label:'Paramètres',icon:SettingsIcon,permission:'settings.write'},
]

function App(){
  const [session,setSession]=useState<Session>(null),[authReady,setAuthReady]=useState(false)
  const [page,setPage]=useState<Page>('overview'),[collapsed,setCollapsed]=useState(false),[mobileOpen,setMobileOpen]=useState(false),[dark,setDark]=useState(()=>localStorage.getItem('bl-theme')==='dark')
  const [data,setData]=useState<Data>(emptyData),[loading,setLoading]=useState(false),[roles,setRoles]=useState<string[]>([]),[permissions,setPermissions]=useState<string[]>([])
  const [searchOpen,setSearchOpen]=useState(false),[profileOpen,setProfileOpen]=useState(false),[query,setQuery]=useState('')
  useEffect(()=>{document.documentElement.classList.toggle('dark',dark);localStorage.setItem('bl-theme',dark?'dark':'light')},[dark])
  useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session as Session);setAuthReady(true)});const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s as Session));return()=>subscription.unsubscribe()},[])
  const load=useCallback(async()=>{
    if(!session){setData(emptyData);setRoles([]);setPermissions([]);return} setLoading(true)
    const {data:ownRoles}=await supabase.from('user_roles').select('role').eq('user_id',session.user.id)
    const roleList=(ownRoles||[]).map(r=>r.role);setRoles(roleList)
    const {data:perms}=await supabase.from('role_permissions').select('role,permission')
    const allowed=(perms||[]).filter(p=>roleList.includes(p.role)).map(p=>p.permission);setPermissions(allowed)
    const staffAllowed=allowed.includes('staff.write')
    const [products,categories,orders,zones,notifications,staff,settings,rates,audit]=await Promise.all([
      supabase.from('products').select('*,product_variants(*),product_images(*),categories(name)').order('created_at',{ascending:false}),
      supabase.from('categories').select('*').order('position'), supabase.from('orders').select('*,order_items(*),shipping_zones(name)').order('created_at',{ascending:false}),
      supabase.from('shipping_zones').select('*').order('name'),supabase.from('notifications').select('*,orders(order_number)').order('created_at',{ascending:false}),
      staffAllowed?supabase.from('profiles').select('*,user_roles(role)').order('created_at'):Promise.resolve({data:[]}),
      supabase.from('store_settings').select('*'),supabase.from('exchange_rates').select('*').order('effective_at',{ascending:false}),
      allowed.includes('audit.read')?supabase.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(100):Promise.resolve({data:[]})
    ])
    const errors=[products,categories,orders,zones,notifications,settings,rates].find(r=>r.error)
    if(errors?.error) toast.error('Chargement incomplet : '+errors.error.message)
    setData({products:(products.data||[]) as Product[],categories:(categories.data||[]) as Category[],orders:(orders.data||[]) as Order[],zones:(zones.data||[]) as Zone[],notifications:(notifications.data||[]) as Notification[],staff:(staff.data||[]) as Staff[],settings:(settings.data||[]) as Settings[],rates:(rates.data||[]) as ExchangeRate[],audit:(audit.data||[]) as Audit[]});setLoading(false)
  },[session])
  useEffect(()=>{void load()},[load])
  const can=(permission:string)=>permissions.includes(permission)
  const logout=async()=>{await supabase.auth.signOut();setPage('overview');setProfileOpen(false)}
  if(!authReady)return <div className="boot"><img src="/bielumina-logo.png" alt="BIELUMINA"/><Loader2 className="spin"/></div>
  if(!session)return <Login/>
  if(!roles.length)return <div className="access-denied"><img src="/bielumina-logo.png" alt=""/><ShieldCheck/><h1>Accès administrateur requis</h1><p>Ce compte n’a aucun rôle dans l’espace BIELUMINA.</p><button className="btn secondary" onClick={logout}>Se déconnecter</button></div>
  const active=nav.find(n=>n.id===page)!
  const go=(p:Page)=>{setPage(p);setMobileOpen(false);setSearchOpen(false);setQuery('')}
  const searchResults=query.trim().length>1?[...data.products.map(p=>({id:p.id,title:p.name,meta:p.sku,page:'products' as Page})),...data.orders.map(o=>({id:o.id,title:o.order_number,meta:o.customer_name,page:'orders' as Page}))].filter(x=>(x.title+x.meta).toLowerCase().includes(query.toLowerCase())).slice(0,7):[]
  const pageProps={data,reload:load,can,roles}
  return <div className={`dash-root admin-shell ${collapsed?'is-collapsed':''}`}>
    <aside className={`sidebar ${mobileOpen?'mobile-open':''}`}>
      <div className="brand"><img src="/bielumina-logo.png" alt=""/><div><strong>BIELUMINA</strong><span>ADMINISTRATION</span></div><button className="icon-btn mobile-close" onClick={()=>setMobileOpen(false)} aria-label="Fermer"><X/></button></div>
      <div className="sidebar-label">ESPACE DE TRAVAIL</div>
      <nav>{nav.filter(n=>!n.permission||can(n.permission)).map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>go(n.id)} title={n.label}><n.icon/><span>{n.label}</span>{n.id==='orders'&&data.orders.filter(o=>o.status==='pending_confirmation').length>0&&<b>{data.orders.filter(o=>o.status==='pending_confirmation').length}</b>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="security-note"><ShieldCheck/><div><strong>Session sécurisée</strong><span>Permissions Supabase RLS</span></div></div><button className="collapse-btn" onClick={()=>setCollapsed(!collapsed)}>{collapsed?<PanelLeftOpen/>:<PanelLeftClose/>}<span>Réduire le menu</span></button></div>
    </aside>
    {mobileOpen&&<button className="sidebar-backdrop" onClick={()=>setMobileOpen(false)} aria-label="Fermer le menu"/>}
    <div className="main-shell">
      <header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobileOpen(true)} aria-label="Ouvrir le menu"><Menu/></button><div className="top-title"><span>BIELUMINA /</span><strong>{active.label}</strong></div>
        <button className="global-search" onClick={()=>setSearchOpen(true)}><Search/><span>Rechercher un produit, une commande…</span><kbd>⌘ K</kbd></button>
        <div className="top-actions"><button className="icon-btn" onClick={()=>setDark(!dark)} aria-label="Changer de thème">{dark?<Sun/>:<Moon/>}</button><button className="icon-btn notification-btn" onClick={()=>go('notifications')} aria-label="Notifications"><Bell/>{data.notifications.filter(n=>n.status==='failed').length>0&&<i/>}</button><div className="profile-wrap"><button className="profile-button" onClick={()=>setProfileOpen(!profileOpen)}><span className="avatar">{(session.user.email||'B')[0].toUpperCase()}</span><div><strong>{session.user.email?.split('@')[0]}</strong><span>{roles[0]?.replaceAll('_',' ')}</span></div><ChevronDown/></button>{profileOpen&&<div className="profile-menu"><span>{session.user.email}</span><button onClick={()=>go('settings')}><SettingsIcon/>Paramètres</button><button onClick={logout}><LogOut/>Se déconnecter</button></div>}</div></div>
      </header>
      <main className="content">{page==='overview'&&<Overview {...pageProps} go={go}/>} {page==='products'&&<Products {...pageProps}/>} {page==='orders'&&<Orders {...pageProps}/>} {page==='pricing'&&<Pricing {...pageProps}/>} {page==='shipping'&&<Shipping {...pageProps}/>} {page==='customers'&&<Customers {...pageProps}/>} {page==='notifications'&&<Notifications {...pageProps}/>} {page==='team'&&<Team {...pageProps}/>} {page==='settings'&&<SettingsPage {...pageProps}/>}</main>
      <footer className="admin-footer"><span>BIELUMINA · Élégance, qualité, vous.</span><span>Données synchronisées avec Supabase <i className="live-dot"/></span></footer>
    </div>
    {loading&&<div className="refresh-indicator"><Loader2 className="spin"/>Actualisation</div>}
    {searchOpen&&<Modal title="Recherche globale" onClose={()=>setSearchOpen(false)} wide={false}><div className="modal-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Numéro, client, produit ou SKU…"/></div><div className="search-results">{searchResults.map(r=><button key={r.id} onClick={()=>go(r.page)}><span><strong>{r.title}</strong><small>{r.meta}</small></span><ArrowRight/></button>)}{query.length>1&&!searchResults.length&&<Empty icon={Search} title="Aucun résultat" text="Essayez un autre terme."/>}</div></Modal>}
    
  </div>
}

function Login(){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');const{error}=await supabase.auth.signInWithPassword({email,password});if(error)setError('Identifiants incorrects ou accès indisponible.');setBusy(false)};return <main className="login-page"><section className="login-story"><img src="/bielumina-logo.png" alt="BIELUMINA"/><div><span className="eyebrow">L’ART DE BIEN GÉRER</span><h1>Votre boutique.<br/><em>Votre lumière.</em></h1><p>Un espace unique pour orchestrer vos produits, vos commandes et chaque relation client.</p></div><small>ÉLÉGANCE · QUALITÉ · VOUS</small></section><section className="login-form-wrap"><form onSubmit={submit} className="login-form"><div className="mobile-login-logo"><img src="/bielumina-logo.png" alt="BIELUMINA"/></div><span className="eyebrow">ESPACE ADMINISTRATION</span><h2>Heureux de vous revoir.</h2><p>Connectez-vous pour accéder à votre tableau de bord.</p><label>Adresse e-mail<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="admin@bielumina.com"/></label><label>Mot de passe<input type="password" required minLength={8} autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••••••"/></label>{error&&<div className="form-error">{error}</div>}<button className="btn primary full" disabled={busy}>{busy?<Loader2 className="spin"/>:<ArrowRight/>}{busy?'Connexion…':'Accéder au dashboard'}</button><div className="login-security"><ShieldCheck/>Connexion chiffrée · Accès contrôlé par rôle</div></form></section></main>}

function PageHead({eyebrow,title,text,children}:{eyebrow?:string;title:string;text:string;children?:ReactNode}){return <div className="page-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{text}</p></div><div className="page-actions">{children}</div></div>}
function Stat({label,value,detail,icon:Icon,tone='gold',trend}:{label:string;value:string;detail:string;icon:typeof Box;tone?:string;trend?:number}){return <article className={`stat-card ${tone}`}><div className="stat-top"><span>{label}</span><Icon/></div><strong>{value}</strong><div className="stat-detail">{trend!==undefined&&(trend>=0?<ArrowUpRight className="positive"/>:<ArrowDownRight className="negative"/>)}<span>{detail}</span></div></article>}
function Badge({children,tone}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone||''}`}>{children}</span>}
function statusTone(status:Status){return status==='delivered'?'success':status==='cancelled'?'danger':status==='pending_confirmation'?'warning':'info'}
function Empty({icon:Icon,title,text}:{icon:typeof Box;title:string;text:string}){return <div className="empty"><Icon/><h3>{title}</h3><p>{text}</p></div>}
function Modal({title,onClose,children,wide=true}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}){useEffect(()=>{const h=(e:KeyboardEvent)=>e.key==='Escape'&&onClose();document.addEventListener('keydown',h);return()=>document.removeEventListener('keydown',h)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`}><header><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Fermer"><X/></button></header><div className="modal-body">{children}</div></section></div>}
function Pagination({page,setPage,total,perPage=8}:{page:number;setPage:(n:number)=>void;total:number;perPage?:number}){const pages=Math.max(1,Math.ceil(total/perPage));return <div className="pagination"><span>{total} résultat{total>1?'s':''}</span><div><button className="icon-btn" disabled={page<=1} onClick={()=>setPage(page-1)}><ChevronLeft/></button><span>Page {Math.min(page,pages)} / {pages}</span><button className="icon-btn" disabled={page>=pages} onClick={()=>setPage(page+1)}><ChevronRight/></button></div></div>}
type CommonProps={data:Data;reload:()=>Promise<void>;can:(p:string)=>boolean;roles:string[]}

function Overview({data,go}:CommonProps&{go:(p:Page)=>void}){
 const {orders,products}=data;const paid=orders.filter(o=>o.payment_status==='paid'&&o.status!=='cancelled');const revenue=(c:Currency)=>paid.filter(o=>o.currency===c).reduce((s,o)=>s+Number(o.total),0)
 const sales=useMemo(()=>{const map=new Map<string,{date:string;HTG:number;USD:number;commandes:number}>();orders.filter(o=>o.status!=='cancelled').forEach(o=>{const d=o.created_at.slice(0,10);const row=map.get(d)||{date:d,HTG:0,USD:0,commandes:0};row[o.currency]+=Number(o.total);row.commandes++;map.set(d,row)});return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date)).slice(-14)},[orders])
 const statuses=Object.entries(statusLabels).map(([key,label])=>({name:label,value:orders.filter(o=>o.status===key).length,key})).filter(s=>s.value)
 const low=products.filter(p=>!p.archived&&p.product_variants.some(v=>v.stock_qty<=p.low_stock_threshold));const stock=products.reduce((s,p)=>s+p.product_variants.reduce((a,v)=>a+v.stock_qty,0),0)
 const top=Object.values(orders.flatMap(o=>o.order_items).reduce<Record<string,{name:string;qty:number;revenue:number;currency:Currency}>>((a,i)=>{a[i.product_name]??={name:i.product_name,qty:0,revenue:0,currency:i.currency};a[i.product_name].qty+=i.quantity;a[i.product_name].revenue+=Number(i.line_total);return a},{})).sort((a,b)=>b.qty-a.qty).slice(0,5)
 const colors=['#c69b38','#22201d','#8c857b','#e1c887','#9f3333','#b8ae9d','#5f7869']
 return <><PageHead eyebrow="PILOTAGE EN TEMPS RÉEL" title="Bonjour, votre boutique en un regard." text="Suivez l’activité, anticipez les stocks et gardez chaque commande sous contrôle."><button className="btn secondary" onClick={()=>location.reload()}><RefreshCw/>Actualiser</button><button className="btn primary" onClick={()=>go('products')}><Plus/>Nouveau produit</button></PageHead>
 <section className="stats-grid"><Stat label="Revenu confirmé · HTG" value={money(revenue('HTG'))} detail={`${paid.filter(o=>o.currency==='HTG').length} commande(s) payée(s)`} icon={WalletCards}/><Stat label="Revenu confirmé · USD" value={money(revenue('USD'),'USD')} detail="Revenus isolés par devise" icon={CircleDollarSign} tone="ink"/><Stat label="Commandes" value={String(orders.length)} detail={`${orders.filter(o=>o.status==='pending_confirmation').length} en attente de confirmation`} icon={ShoppingBag} tone="sand"/><Stat label="Stock disponible" value={String(stock)} detail={`${low.length} alerte(s) de stock faible`} icon={PackageCheck} tone="sage"/></section>
 <section className="dashboard-grid"><article className="panel sales-panel"><div className="panel-head"><div><span className="eyebrow">PERFORMANCE</span><h2>Évolution des ventes</h2><p>Montants bruts des commandes non annulées, sans conversion entre devises.</p></div><div className="chart-legend"><span><i className="gold-dot"/>HTG</span><span><i className="ink-dot"/>USD</span></div></div>{sales.length?<div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={sales}><defs><linearGradient id="goldArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c69b38" stopOpacity=".3"/><stop offset="1" stopColor="#c69b38" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line)"/><XAxis dataKey="date" tickFormatter={d=>new Date(d).toLocaleDateString('fr-FR',{day:'2-digit',month:'short'})} axisLine={false} tickLine={false}/><YAxis yAxisId="htg" orientation="left" tickFormatter={shortMoney} axisLine={false} tickLine={false}/><YAxis yAxisId="usd" orientation="right" tickFormatter={shortMoney} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'var(--surface)',border:'1px solid var(--line)',borderRadius:12}} labelFormatter={d=>dateFr(String(d))}/><Area yAxisId="htg" type="monotone" dataKey="HTG" stroke="#c69b38" fill="url(#goldArea)" strokeWidth={2.5}/><Area yAxisId="usd" type="monotone" dataKey="USD" stroke="var(--text)" fill="transparent" strokeWidth={2}/></AreaChart></ResponsiveContainer></div>:<Empty icon={ClipboardList} title="Aucune vente à tracer" text="Le graphique apparaîtra dès la première commande."/>}</article>
 <article className="panel status-panel"><div className="panel-head"><div><span className="eyebrow">FLUX</span><h2>État des commandes</h2></div></div>{statuses.length?<><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={statuses} dataKey="value" innerRadius={58} outerRadius={82} paddingAngle={3} stroke="none">{statuses.map((s,i)=><Cell key={s.key} fill={colors[i%colors.length]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div><strong>{orders.length}</strong><span>Total</span></div></div><div className="status-list">{statuses.map((s,i)=><div key={s.key}><span><i style={{background:colors[i%colors.length]}}/>{s.name}</span><strong>{s.value}</strong></div>)}</div></>:<Empty icon={ShoppingBag} title="Aucune commande" text="Les statuts seront répartis ici."/>}</article></section>
 <section className="dashboard-grid lower"><article className="panel"><div className="panel-head"><div><span className="eyebrow">À TRAITER</span><h2>Dernières commandes</h2></div><button className="text-btn" onClick={()=>go('orders')}>Tout voir<ArrowRight/></button></div><div className="compact-list">{orders.slice(0,5).map(o=><button key={o.id} onClick={()=>go('orders')}><span className="order-icon"><ShoppingBag/></span><span><strong>{o.order_number}</strong><small>{o.customer_name} · {dateFr(o.created_at)}</small></span><span className="align-right"><strong>{money(o.total,o.currency)}</strong><Badge tone={statusTone(o.status)}>{statusLabels[o.status]}</Badge></span></button>)}{!orders.length&&<Empty icon={ShoppingBag} title="Aucune commande" text="Les nouvelles commandes apparaîtront ici."/>}</div></article>
 <article className="panel"><div className="panel-head"><div><span className="eyebrow">CATALOGUE</span><h2>Produits les plus vendus</h2></div><button className="text-btn" onClick={()=>go('products')}>Catalogue<ArrowRight/></button></div><div className="top-products">{top.map((p,i)=><div key={p.name}><span className="rank">0{i+1}</span><span><strong>{p.name}</strong><small>{p.qty} article(s) vendu(s)</small></span><strong>{money(p.revenue,p.currency)}</strong></div>)}{!top.length&&<Empty icon={Box} title="Pas encore de ventes" text="Le classement se construira automatiquement."/>}</div></article></section>
 {low.length>0&&<section className="stock-alert"><div><span className="alert-icon"><Box/></span><div><strong>Les stocks demandent votre attention</strong><p>{low.slice(0,3).map(p=>p.name).join(' · ')}{low.length>3?` et ${low.length-3} autre(s)`:''}</p></div></div><button className="btn secondary" onClick={()=>go('products')}>Vérifier les stocks<ArrowRight/></button></section>}
 </>
}

function Products({data,reload,can}:CommonProps){
 const[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[page,setPage]=useState(1),[editing,setEditing]=useState<Product|null|undefined>(undefined),[selected,setSelected]=useState<string[]>([])
 const rate=Number(data.settings.find(s=>s.key==='commerce')?.value.exchange_rate||135)
 const filtered=data.products.filter(p=>(p.name+p.sku).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||(filter==='published'&&p.published&&!p.archived)||(filter==='draft'&&!p.published)||(filter==='archived'&&p.archived)||(filter==='low'&&p.product_variants.some(v=>v.stock_qty<=p.low_stock_threshold))))
 const rows=filtered.slice((page-1)*8,page*8)
 const toggleStatus=async(p:Product,key:'published'|'archived')=>{const{error}=await supabase.from('products').update({[key]:!p[key],updated_at:new Date().toISOString()}).eq('id',p.id);if(error)toast.error(error.message);else{toast.success('Catalogue mis à jour');await reload()}}
 const bulk=async(action:'publish'|'archive')=>{if(!selected.length)return;if(!window.confirm(`Appliquer cette action à ${selected.length} produit(s) ?`))return;const{error}=await supabase.from('products').update(action==='publish'?{published:true,archived:false}:{archived:true,published:false}).in('id',selected);if(error)toast.error(error.message);else{toast.success('Modification en lot terminée');setSelected([]);await reload()}}
 const exportCsv=()=>{const csv=['Nom;SKU;Prix HTG;Prix USD;Stock;Publié',...filtered.map(p=>`${p.name};${p.sku};${p.price_htg};${p.price_usd};${p.product_variants.reduce((s,v)=>s+v.stock_qty,0)};${p.published?'Oui':'Non'}`)].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='catalogue-bielumina.csv';a.click()}
 return <><PageHead eyebrow="CATALOGUE" title="Produits et inventaire" text="Présentez chaque pièce avec soin et gardez vos stocks parfaitement à jour."><button className="btn secondary" onClick={exportCsv}><Download/>Exporter</button>{can('products.write')&&<button className="btn primary" onClick={()=>setEditing(null)}><Plus/>Ajouter un produit</button>}</PageHead>
 <section className="mini-stats"><div><span>PRODUITS PUBLIÉS</span><strong>{data.products.filter(p=>p.published&&!p.archived).length}</strong></div><div><span>BROUILLONS</span><strong>{data.products.filter(p=>!p.published&&!p.archived).length}</strong></div><div><span>STOCK FAIBLE</span><strong>{data.products.filter(p=>p.product_variants.some(v=>v.stock_qty<=p.low_stock_threshold)).length}</strong></div><div><span>ARCHIVÉS</span><strong>{data.products.filter(p=>p.archived).length}</strong></div></section>
 <section className="panel table-panel"><div className="table-toolbar"><div className="search-field"><Search/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Rechercher par nom ou SKU…"/></div><select value={filter} onChange={e=>{setFilter(e.target.value);setPage(1)}}><option value="all">Tous les produits</option><option value="published">Publiés</option><option value="draft">Brouillons</option><option value="low">Stock faible</option><option value="archived">Archivés</option></select>{selected.length>0&&can('products.write')&&<div className="bulk-actions"><span>{selected.length} sélectionné(s)</span><button onClick={()=>bulk('publish')}>Publier</button><button onClick={()=>bulk('archive')}>Archiver</button></div>}</div>
 <div className="table-scroll"><table><thead><tr><th>{can('products.write')&&<input type="checkbox" aria-label="Tout sélectionner" checked={rows.length>0&&rows.every(p=>selected.includes(p.id))} onChange={e=>setSelected(e.target.checked?[...new Set([...selected,...rows.map(p=>p.id)])]:selected.filter(id=>!rows.some(p=>p.id===id)))}/>}</th><th>Produit</th><th>Prix</th><th>Stock</th><th>Statut</th><th>Mise à jour</th><th></th></tr></thead><tbody>{rows.map(p=>{const qty=p.product_variants.reduce((s,v)=>s+v.stock_qty,0);const storedImage=p.product_images?.[0]?.storage_path;const img=storedImage||(p.image_path?.startsWith('/images/')?null:p.image_path);return <tr key={p.id}><td>{can('products.write')&&<input type="checkbox" aria-label={`Sélectionner ${p.name}`} checked={selected.includes(p.id)} onChange={e=>setSelected(e.target.checked?[...selected,p.id]:selected.filter(id=>id!==p.id))}/>}</td><td><div className="product-cell">{img?<img src={img.startsWith('http')?img:supabase.storage.from('product-images').getPublicUrl(img).data.publicUrl} alt=""/>:<span className="product-placeholder"><Box/></span>}<div><strong>{p.name}</strong><small>{p.sku} · {p.categories?.name||'Sans catégorie'}</small></div></div></td><td><strong>{money(p.price_htg)}</strong><small className="cell-sub">{money(p.price_usd,'USD')}</small></td><td><strong className={qty<=p.low_stock_threshold?'text-danger':''}>{qty}</strong><small className="cell-sub">Seuil : {p.low_stock_threshold}</small></td><td><Badge tone={p.archived?'neutral':p.published?'success':'warning'}>{p.archived?'Archivé':p.published?'Publié':'Brouillon'}</Badge></td><td><span className="muted">{p.product_variants.length} variante(s)</span></td><td><div className="row-actions">{can('products.write')&&<><button className="icon-btn" onClick={()=>setEditing(p)} title="Modifier"><Edit3/></button><button className="icon-btn" onClick={()=>toggleStatus(p,p.archived?'archived':'published')} title={p.archived?'Restaurer':p.published?'Dépublier':'Publier'}>{p.archived?<RefreshCw/>:p.published?<Eye/>:<Upload/>}</button></>}</div></td></tr>})}</tbody></table>{!rows.length&&<Empty icon={Box} title="Aucun produit trouvé" text="Modifiez votre recherche ou ajoutez un produit au catalogue."/>}</div><Pagination page={page} setPage={setPage} total={filtered.length}/></section>
 {editing!==undefined&&<ProductForm product={editing} categories={data.categories} rate={rate} onClose={()=>setEditing(undefined)} onSaved={async()=>{setEditing(undefined);await reload()}}/>}</>
}

function ProductForm({product,categories,rate,onClose,onSaved}:{product:Product|null;categories:Category[];rate:number;onClose:()=>void;onSaved:()=>Promise<void>}){
 const[form,setForm]=useState({name:product?.name||'',sku:product?.sku||'',description:product?.description||'',category_id:product?.category_id||'',price_htg:String(product?.price_htg??''),price_usd:String(product?.price_usd??''),low_stock_threshold:String(product?.low_stock_threshold??3),stock:String(product?.product_variants.reduce((s,v)=>s+v.stock_qty,0)||0),published:product?.published||false,price_reference:product?.price_reference||'HTG' as Currency,price_mode:product?.price_mode||'manual'})
 const[files,setFiles]=useState<FileList|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const set=(k:string,v:string|boolean)=>setForm(f=>({...f,[k]:v}))
 const priceChange=(currency:Currency,value:string)=>{setForm(f=>({...f,[currency==='HTG'?'price_htg':'price_usd']:value,...(f.price_mode==='automatic'&&value?{[currency==='HTG'?'price_usd':'price_htg']:String(convertPrice(Number(value),currency,rate))}:{})}))}
 const submit=async(e:FormEvent)=>{e.preventDefault();setError('');if(Number(form.price_htg)<0||Number(form.price_usd)<0){setError('Les prix doivent être positifs.');return}setBusy(true)
  const payload={name:form.name.trim(),slug:slugify(form.name),sku:form.sku.trim().toUpperCase(),description:form.description.trim(),category_id:form.category_id||null,price_htg:Number(form.price_htg),price_usd:Number(form.price_usd),low_stock_threshold:Number(form.low_stock_threshold),published:form.published,price_reference:form.price_reference,price_mode:form.price_mode,updated_at:new Date().toISOString()}
  const result=product?await supabase.from('products').update(payload).eq('id',product.id).select().single():await supabase.from('products').insert({...payload,featured:false,is_new:true}).select().single()
  if(result.error){setError(result.error.message);setBusy(false);return}const id=product?.id||result.data.id
  if(product){await supabase.from('product_variants').update({stock_qty:Number(form.stock)}).eq('product_id',id)}else await supabase.from('product_variants').insert({product_id:id,sku:`${form.sku}-STD`,name:'Standard',stock_qty:Number(form.stock)})
  if(files)for(const file of Array.from(files)){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){setError('Images JPG, PNG ou WebP de 5 Mo maximum.');setBusy(false);return}const path=`${id}/${crypto.randomUUID()}.${file.name.split('.').pop()}`;const up=await supabase.storage.from('product-images').upload(path,file);if(up.error){setError(up.error.message);setBusy(false);return}await supabase.from('product_images').insert({product_id:id,storage_path:path})}
  toast.success(product?'Produit modifié':'Produit ajouté au catalogue');setBusy(false);await onSaved()
 }
 return <Modal title={product?'Modifier le produit':'Nouveau produit'} onClose={onClose}><form onSubmit={submit} className="form-grid"><label className="span-2">Nom du produit<input required minLength={2} value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>SKU<input required value={form.sku} onChange={e=>set('sku',e.target.value)}/></label><label>Catégorie<select value={form.category_id} onChange={e=>set('category_id',e.target.value)}><option value="">Sans catégorie</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="span-2">Description<textarea rows={3} value={form.description} onChange={e=>set('description',e.target.value)}/></label><div className="span-2 form-section"><strong>Prix et conversion</strong><div className="inline-fields"><select value={form.price_reference} onChange={e=>set('price_reference',e.target.value)}><option value="HTG">Référence HTG</option><option value="USD">Référence USD</option></select><select value={form.price_mode} onChange={e=>set('price_mode',e.target.value)}><option value="manual">Prix manuels</option><option value="automatic">Calcul automatique</option></select></div></div><label>Prix HTG<input type="number" min="0" step="0.01" required value={form.price_htg} onChange={e=>priceChange('HTG',e.target.value)}/></label><label>Prix USD<input type="number" min="0" step="0.01" required value={form.price_usd} onChange={e=>priceChange('USD',e.target.value)}/></label><label>Stock total<input type="number" min="0" step="1" required value={form.stock} onChange={e=>set('stock',e.target.value)}/></label><label>Seuil d’alerte<input type="number" min="0" step="1" required value={form.low_stock_threshold} onChange={e=>set('low_stock_threshold',e.target.value)}/></label><label className="span-2 file-input"><ImagePlus/><span>Ajouter des images<small>JPG, PNG ou WebP · 5 Mo maximum par image</small></span><input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>setFiles(e.target.files)}/></label><label className="check-label span-2"><input type="checkbox" checked={form.published} onChange={e=>set('published',e.target.checked)}/>Publier immédiatement dans la boutique</label>{error&&<div className="form-error span-2">{error}</div>}<div className="form-actions span-2"><button type="button" className="btn secondary" onClick={onClose}>Annuler</button><button className="btn primary" disabled={busy}>{busy?<Loader2 className="spin"/>:<Check/>}{busy?'Enregistrement…':'Enregistrer le produit'}</button></div></form></Modal>
}

function Orders({data,reload,can}:CommonProps){
 const[query,setQuery]=useState(''),[status,setStatus]=useState('all'),[page,setPage]=useState(1),[selected,setSelected]=useState<Order|null>(null)
 const filtered=data.orders.filter(o=>(o.order_number+o.customer_name+o.phone).toLowerCase().includes(query.toLowerCase())&&(status==='all'||o.status===status));const rows=filtered.slice((page-1)*8,page*8)
 return <><PageHead eyebrow="VENTES" title="Commandes" text="Du premier contact à la livraison, chaque étape reste claire et traçable."><button className="btn secondary" onClick={()=>reload()}><RefreshCw/>Actualiser</button></PageHead>
 <section className="order-status-strip">{(['pending_confirmation','confirmed','processing','shipped','delivered'] as Status[]).map(s=><button key={s} onClick={()=>setStatus(s)} className={status===s?'active':''}><span>{statusLabels[s]}</span><strong>{data.orders.filter(o=>o.status===s).length}</strong></button>)}</section>
 <section className="panel table-panel"><div className="table-toolbar"><div className="search-field"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="N° de commande, client ou téléphone…"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Tous les statuts</option>{Object.entries(statusLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><div className="table-scroll"><table><thead><tr><th>Commande</th><th>Client</th><th>Date</th><th>Total</th><th>Paiement</th><th>Statut</th><th></th></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><button className="order-link" onClick={()=>setSelected(o)}>{o.order_number}</button><small className="cell-sub">{o.order_items.reduce((s,i)=>s+i.quantity,0)} article(s)</small></td><td><strong>{o.customer_name}</strong><small className="cell-sub">{o.phone}</small></td><td>{dateFr(o.created_at)}<small className="cell-sub">{new Date(o.created_at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</small></td><td><strong>{money(o.total,o.currency)}</strong><small className="cell-sub">Livraison {money(o.shipping_fee,o.currency)}</small></td><td><Badge tone={o.payment_status==='paid'?'success':o.payment_status==='failed'?'danger':'warning'}>{paymentLabels[o.payment_status]}</Badge></td><td><Badge tone={statusTone(o.status)}>{statusLabels[o.status]}</Badge></td><td><button className="icon-btn" onClick={()=>setSelected(o)}><ChevronRight/></button></td></tr>)}</tbody></table>{!rows.length&&<Empty icon={ClipboardList} title="Aucune commande" text="Aucune commande ne correspond à ces critères."/>}</div><Pagination page={page} setPage={setPage} total={filtered.length}/></section>
 {selected&&<OrderDetail order={selected} can={can} onClose={()=>setSelected(null)} onSaved={async()=>{setSelected(null);await reload()}}/>}</>
}
function OrderDetail({order,can,onClose,onSaved}:{order:Order;can:(p:string)=>boolean;onClose:()=>void;onSaved:()=>Promise<void>}){
 const[note,setNote]=useState(''),[busy,setBusy]=useState(false),[history,setHistory]=useState<{id:string;from_status:Status|null;to_status:Status;note:string;created_at:string}[]>([]),[tab,setTab]=useState<'details'|'history'|'notifications'>('details')
 useEffect(()=>{supabase.from('order_status_history').select('*').eq('order_id',order.id).order('created_at',{ascending:false}).then(({data})=>setHistory((data||[]) as typeof history))},[order.id])
 const updateStatus=async(s:Status)=>{if(!note.trim()&&!window.confirm(`Confirmer le passage au statut « ${statusLabels[s]} » ?`))return;setBusy(true);const{error}=await supabase.rpc('admin_update_order_status',{p_order_id:order.id,p_status:s,p_note:note});setBusy(false);if(error)toast.error(error.message);else{toast.success('Statut mis à jour et historisé');await onSaved()}}
 const updatePayment=async(s:PaymentStatus)=>{setBusy(true);const{error}=await supabase.rpc('admin_update_payment_status',{p_order_id:order.id,p_status:s,p_reference:'Mise à jour depuis le dashboard'});setBusy(false);if(error)toast.error(error.message);else{toast.success('Paiement mis à jour');await onSaved()}}
 return <Modal title={order.order_number} onClose={onClose}><div className="order-detail-head"><div><Badge tone={statusTone(order.status)}>{statusLabels[order.status]}</Badge><p>Créée le {dateFr(order.created_at)} · {order.currency}{order.exchange_rate?` · Taux ${order.exchange_rate}`:''}</p></div><strong>{money(order.total,order.currency)}</strong></div><div className="tabs"><button className={tab==='details'?'active':''} onClick={()=>setTab('details')}>Détails</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>Historique</button><button className={tab==='notifications'?'active':''} onClick={()=>setTab('notifications')}>Notifications</button></div>
 {tab==='details'&&<><div className="detail-grid"><section><h3>Client</h3><p><strong>{order.customer_name}</strong><br/>{order.phone}<br/>{order.email||'Aucun e-mail'}</p></section><section><h3>Livraison</h3><p>{order.shipping_zones?.name||'Zone non précisée'}<br/>{order.delivery_address||'Adresse non précisée'}<br/>{order.instructions}</p></section></div><div className="order-lines"><h3>Articles commandés</h3>{order.order_items.map(i=><div key={i.id}><span><strong>{i.product_name}</strong><small>{i.variant_name} · {i.sku} · Qté {i.quantity}</small></span><span>{money(i.unit_price,i.currency)} × {i.quantity}<strong>{money(i.line_total,i.currency)}</strong></span></div>)}<div className="order-totals"><p>Sous-total <strong>{money(order.subtotal,order.currency)}</strong></p><p>Livraison <strong>{money(order.shipping_fee,order.currency)}</strong></p>{order.discount>0&&<p>Remise <strong>−{money(order.discount,order.currency)}</strong></p>}<p className="total">Total <strong>{money(orderTotal(Number(order.subtotal),Number(order.shipping_fee),Number(order.discount)),order.currency)}</strong></p></div></div>
 {can('orders.write')&&nextStatuses[order.status].length>0&&<div className="status-action"><h3>Faire progresser la commande</h3><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Note interne facultative, conservée dans l’historique…"/><div>{nextStatuses[order.status].map(s=><button key={s} disabled={busy} className={`btn ${s==='cancelled'?'danger':'primary'}`} onClick={()=>updateStatus(s)}>{s==='cancelled'?<X/>:<ArrowRight/>}{statusLabels[s]}</button>)}</div></div>}{can('payment.write')&&<div className="payment-action"><span>Statut du paiement</span><select disabled={busy} value={order.payment_status} onChange={e=>updatePayment(e.target.value as PaymentStatus)}>{Object.entries(paymentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div>}</>}
 {tab==='history'&&<div className="timeline">{history.map(h=><div key={h.id}><i/><span><strong>{h.from_status?`${statusLabels[h.from_status]} → ${statusLabels[h.to_status]}`:statusLabels[h.to_status]}</strong><small>{dateFr(h.created_at)} · {new Date(h.created_at).toLocaleTimeString('fr-FR')}</small>{h.note&&<p>{h.note}</p>}</span></div>)}{!history.length&&<Empty icon={FileClock} title="Aucun historique" text="Les changements seront consignés ici."/>}</div>}
 {tab==='notifications'&&<div className="info-box"><Bell/><div><strong>Suivi dans le centre de notifications</strong><p>Les envois WhatsApp et e-mail, identifiants fournisseur et tentatives sont centralisés dans l’onglet Notifications.</p></div></div>}</Modal>
}

function Customers({data}:CommonProps){const[query,setQuery]=useState(''),[selected,setSelected]=useState<string|null>(null);const customers=Object.values(data.orders.reduce<Record<string,{name:string;phone:string;email:string;orders:Order[];HTG:number;USD:number}>>((a,o)=>{a[o.phone]??={name:o.customer_name,phone:o.phone,email:o.email||'',orders:[],HTG:0,USD:0};a[o.phone].orders.push(o);if(o.status!=='cancelled')a[o.phone][o.currency]+=Number(o.total);return a},{})).filter(c=>(c.name+c.phone+c.email).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.orders.length-a.orders.length);const active=customers.find(c=>c.phone===selected);return <><PageHead eyebrow="RELATION CLIENT" title="Clients" text="Retrouvez les coordonnées et l’historique d’achat, sans exposer les données au-delà des rôles autorisés."/><section className="panel table-panel"><div className="table-toolbar"><div className="search-field"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Rechercher un client…"/></div></div><div className="table-scroll"><table><thead><tr><th>Client</th><th>Contact</th><th>Commandes</th><th>Cumul HTG</th><th>Cumul USD</th><th>Dernier achat</th><th></th></tr></thead><tbody>{customers.map(c=><tr key={c.phone}><td><div className="customer-cell"><span className="avatar">{c.name[0]}</span><strong>{c.name}</strong></div></td><td>{c.phone}<small className="cell-sub">{c.email||'—'}</small></td><td><strong>{c.orders.length}</strong></td><td>{money(c.HTG)}</td><td>{money(c.USD,'USD')}</td><td>{dateFr(c.orders[0].created_at)}</td><td><button className="icon-btn" onClick={()=>setSelected(c.phone)}><Eye/></button></td></tr>)}</tbody></table>{!customers.length&&<Empty icon={Users} title="Aucun client trouvé" text="Les clients sont créés à partir des commandes réelles."/>}</div></section>{active&&<Modal title={active.name} onClose={()=>setSelected(null)}><div className="detail-grid"><section><h3>Coordonnées</h3><p>{active.phone}<br/>{active.email||'Aucun e-mail'}</p></section><section><h3>Activité</h3><p>{active.orders.length} commande(s)<br/>{money(active.HTG)} · {money(active.USD,'USD')}</p></section></div><div className="compact-list">{active.orders.map(o=><div key={o.id} className="customer-order"><span><strong>{o.order_number}</strong><small>{dateFr(o.created_at)} · {statusLabels[o.status]}</small></span><strong>{money(o.total,o.currency)}</strong></div>)}</div></Modal>}</>}

function Pricing({data,reload,can}:CommonProps){const commerce=data.settings.find(s=>s.key==='commerce')?.value||{};const current=Number(commerce.exchange_rate||135);const[rate,setRate]=useState(String(current)),[note,setNote]=useState(''),[preview,setPreview]=useState(false),[busy,setBusy]=useState(false);const saveRate=async()=>{if(!window.confirm(`Confirmer le nouveau taux : 1 USD = ${rate} HTG ? Les commandes existantes ne seront pas recalculées.`))return;setBusy(true);const{error}=await supabase.rpc('admin_set_exchange_rate',{p_rate:Number(rate),p_note:note});setBusy(false);if(error)toast.error(error.message);else{toast.success('Taux enregistré et journalisé');await reload()}};const updatePrice=async(p:Product,currency:Currency,value:string)=>{const other=convertPrice(Number(value),currency,current);const payload=currency==='HTG'?{price_htg:Number(value),price_usd:other,price_reference:'HTG',price_mode:'automatic'}:{price_usd:Number(value),price_htg:other,price_reference:'USD',price_mode:'automatic'};const{error}=await supabase.from('products').update(payload).eq('id',p.id);if(error)toast.error(error.message);else{toast.success(`${p.name} : prix synchronisés`);await reload()}};const applyBatch=async()=>{setBusy(true);for(const p of data.products.filter(p=>!p.archived)){const ref=p.price_reference;const amount=Number(ref==='HTG'?p.price_htg:p.price_usd);const converted=convertPrice(amount,ref,current);await supabase.from('products').update(ref==='HTG'?{price_usd:converted,price_mode:'automatic'}:{price_htg:converted,price_mode:'automatic'}).eq('id',p.id)}setBusy(false);setPreview(false);toast.success('Conversion du catalogue terminée');await reload()};return <><PageHead eyebrow="FINANCES" title="Prix et devises" text="Convertissez avec précision, prévisualisez chaque changement et préservez l’historique des commandes."/>
 <section className="pricing-hero"><div><span className="eyebrow">TAUX DE RÉFÉRENCE ACTUEL</span><div className="rate-display"><strong>1 USD</strong><ArrowRight/><strong>{current} HTG</strong></div><p>Dernier taux enregistré dans les paramètres commerciaux.</p></div><div className="rate-example"><span>EXEMPLE DE CONVERSION</span><strong>2 700 HTG = {money(convertPrice(2700,'HTG',current),'USD')}</strong><small>2 700 ÷ {current} = {(2700/current).toFixed(2)}</small></div></section>
 {can('settings.write')&&<section className="panel form-panel"><div className="panel-head"><div><span className="eyebrow">SUPER ADMINISTRATEUR</span><h2>Modifier le taux</h2><p>Cette opération est confirmée et consignée dans le journal d’audit.</p></div></div><div className="inline-form"><label>Nouveau taux HTG / USD<input type="number" min="0.01" step="0.01" value={rate} onChange={e=>setRate(e.target.value)}/></label><label>Note de changement<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Motif du nouveau taux…"/></label><button className="btn primary" disabled={busy||Number(rate)<=0} onClick={saveRate}><Check/>Enregistrer le taux</button></div></section>}
 <section className="panel table-panel"><div className="panel-head padded"><div><span className="eyebrow">CATALOGUE</span><h2>Conversion des prix</h2><p>Le prix saisi devient la référence ; l’autre devise est calculée au taux actuel.</p></div>{can('products.write')&&<button className="btn secondary" onClick={()=>setPreview(true)}><Sparkles/>Prévisualiser la conversion en lot</button>}</div><div className="table-scroll"><table><thead><tr><th>Produit</th><th>Prix HTG</th><th>Équivalent USD</th><th>Mode</th><th>Action</th></tr></thead><tbody>{data.products.filter(p=>!p.archived).map(p=><tr key={p.id}><td><strong>{p.name}</strong><small className="cell-sub">Référence : {p.price_reference}</small></td><td><strong>{money(p.price_htg)}</strong></td><td>{money(p.price_usd,'USD')}</td><td><Badge tone={p.price_mode==='automatic'?'info':'neutral'}>{p.price_mode==='automatic'?'Automatique':'Manuel'}</Badge></td><td>{can('products.write')&&<div className="price-edit"><input aria-label={`Nouveau prix HTG pour ${p.name}`} type="number" min="0" placeholder="Prix HTG" onKeyDown={e=>{if(e.key==='Enter')void updatePrice(p,'HTG',e.currentTarget.value)}}/><button className="text-btn" onClick={e=>{const input=e.currentTarget.previousElementSibling as HTMLInputElement;if(input.value)void updatePrice(p,'HTG',input.value)}}>Appliquer</button></div>}</td></tr>)}</tbody></table></div></section>
 {preview&&<Modal title="Prévisualisation de la conversion" onClose={()=>setPreview(false)}><div className="warning-box"><ShieldCheck/><p>Cette action recalculera uniquement la devise secondaire de <strong>{data.products.filter(p=>!p.archived).length} produits</strong>. Les commandes passées resteront strictement inchangées.</p></div><div className="conversion-preview">{data.products.filter(p=>!p.archived).slice(0,10).map(p=>{const amount=Number(p.price_reference==='HTG'?p.price_htg:p.price_usd);return <div key={p.id}><span>{p.name}<small>{p.price_reference} · {money(amount,p.price_reference)}</small></span><ArrowRight/><strong>{money(convertPrice(amount,p.price_reference,current),p.price_reference==='HTG'?'USD':'HTG')}</strong></div>})}</div><div className="form-actions"><button className="btn secondary" onClick={()=>setPreview(false)}>Annuler</button><button className="btn primary" disabled={busy} onClick={applyBatch}>{busy?<Loader2 className="spin"/>:<Check/>}Confirmer la conversion</button></div></Modal>}</>}

function Shipping({data,reload,can}:CommonProps){const[editing,setEditing]=useState<Zone|null|undefined>(undefined);return <><PageHead eyebrow="LOGISTIQUE" title="Livraison et zones" text="Des tarifs lisibles par commune, figés dans chaque commande au moment de sa validation.">{can('orders.write')&&<button className="btn primary" onClick={()=>setEditing(null)}><Plus/>Nouvelle zone</button>}</PageHead><div className="zone-grid">{data.zones.map(z=><article className="zone-card" key={z.id}><div className="zone-top"><span className="zone-icon"><Truck/></span><Badge tone={z.active?'success':'neutral'}>{z.active?'Active':'Inactive'}</Badge></div><h2>{z.name}</h2><p>{z.delivery_type==='express'?'Livraison express':'Livraison standard'}</p><div className="zone-price"><strong>{money(z.fee_htg)}</strong><span>{money(z.fee_usd,'USD')}</span></div>{z.free_threshold&&<small>Gratuite dès {money(z.free_threshold)}</small>}<div className="zone-footer"><span>Frais suppl. {money(z.extra_fee)}</span>{can('orders.write')&&<button className="icon-btn" onClick={()=>setEditing(z)}><Edit3/></button>}</div></article>)}</div>{!data.zones.length&&<Empty icon={Truck} title="Aucune zone" text="Créez votre première zone de livraison."/>}{editing!==undefined&&<ZoneForm zone={editing} onClose={()=>setEditing(undefined)} onSaved={async()=>{setEditing(undefined);await reload()}}/>}</>}
function ZoneForm({zone,onClose,onSaved}:{zone:Zone|null;onClose:()=>void;onSaved:()=>Promise<void>}){const[f,setF]=useState({name:zone?.name||'',fee_htg:String(zone?.fee_htg??250),fee_usd:String(zone?.fee_usd??2),delivery_type:zone?.delivery_type||'standard',free_threshold:String(zone?.free_threshold??''),extra_fee:String(zone?.extra_fee??0),active:zone?.active??true});const[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);const payload={...f,fee_htg:Number(f.fee_htg),fee_usd:Number(f.fee_usd),free_threshold:f.free_threshold?Number(f.free_threshold):null,extra_fee:Number(f.extra_fee)};const r=zone?await supabase.from('shipping_zones').update(payload).eq('id',zone.id):await supabase.from('shipping_zones').insert(payload);setBusy(false);if(r.error)setError(r.error.message);else{toast.success('Zone de livraison enregistrée');await onSaved()}};return <Modal title={zone?'Modifier la zone':'Nouvelle zone de livraison'} onClose={onClose} wide={false}><form className="form-grid" onSubmit={submit}><label className="span-2">Commune ou secteur<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Tarif HTG<input type="number" min="0" required value={f.fee_htg} onChange={e=>setF({...f,fee_htg:e.target.value})}/></label><label>Tarif USD<input type="number" min="0" step="0.01" required value={f.fee_usd} onChange={e=>setF({...f,fee_usd:e.target.value})}/></label><label>Type<select value={f.delivery_type} onChange={e=>setF({...f,delivery_type:e.target.value})}><option value="standard">Standard</option><option value="express">Express</option></select></label><label>Seuil gratuité HTG<input type="number" min="0" value={f.free_threshold} onChange={e=>setF({...f,free_threshold:e.target.value})}/></label><label>Frais supplémentaires<input type="number" min="0" value={f.extra_fee} onChange={e=>setF({...f,extra_fee:e.target.value})}/></label><label className="check-label span-2"><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/>Zone active pour les nouvelles commandes</label>{error&&<div className="form-error span-2">{error}</div>}<div className="form-actions span-2"><button type="button" className="btn secondary" onClick={onClose}>Annuler</button><button className="btn primary" disabled={busy}>Enregistrer</button></div></form></Modal>}

function Notifications({data,reload,can}:CommonProps){const[filter,setFilter]=useState('all'),[busy,setBusy]=useState(false);const rows=data.notifications.filter(n=>filter==='all'||n.status===filter);const retry=async(id:string)=>{const{error}=await supabase.rpc('admin_retry_notification',{p_notification_id:id});if(error)toast.error(error.message);else{toast.success('Notification replacée dans la file');await reload()}};const test=async()=>{setBusy(true);const{error}=await supabase.functions.invoke('whatsapp-notifications',{body:{action:'test'}});setBusy(false);if(error)toast.error(error.message);else toast.success('Flux de test exécuté sans message réel')};const failed=rows.filter(n=>n.status==='failed').length;return <><PageHead eyebrow="MESSAGERIE TRANSACTIONNELLE" title="Notifications WhatsApp" text="Suivez chaque envoi, chaque réponse Meta et chaque nouvelle tentative sans risque de doublon."><button className="btn secondary" onClick={test} disabled={busy}><Sparkles/>Tester le flux</button></PageHead><div className="warning-box top-warning"><ShieldCheck/><div><strong>Mode sécurisé</strong><p>Si les identifiants Meta ne sont pas configurés côté serveur, le test reste en simulation et aucun message réel n’est envoyé. Les secrets ne transitent jamais par le navigateur.</p></div></div><section className="mini-stats three"><div><span>ENVOYÉES</span><strong>{data.notifications.filter(n=>n.status==='sent').length}</strong></div><div><span>EN FILE</span><strong>{data.notifications.filter(n=>['pending','processing'].includes(n.status)).length}</strong></div><div><span>ÉCHECS</span><strong>{failed}</strong></div></section><section className="panel table-panel"><div className="table-toolbar"><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Tous les états</option><option value="pending">En attente</option><option value="sent">Envoyées</option><option value="failed">Échecs</option></select></div><div className="table-scroll"><table><thead><tr><th>Canal</th><th>Commande</th><th>Destinataire</th><th>Statut</th><th>Tentatives</th><th>Dernier essai</th><th></th></tr></thead><tbody>{rows.map(n=><tr key={n.id}><td><Badge tone="neutral">{n.channel==='whatsapp'?'WhatsApp':'E-mail'}</Badge></td><td>{n.orders?.order_number||'—'}</td><td>{n.recipient}</td><td><Badge tone={n.status==='sent'?'success':n.status==='failed'?'danger':'warning'}>{n.status==='sent'?'Envoyée':n.status==='failed'?'Échec':n.status==='pending'?'En file':'En cours'}</Badge>{n.error_code&&<small className="cell-sub text-danger">{n.error_code}</small>}</td><td>{n.attempts}</td><td>{n.last_attempt_at?dateFr(n.last_attempt_at):'—'}</td><td>{n.status==='failed'&&can('orders.write')&&<button className="text-btn" onClick={()=>retry(n.id)}><RefreshCw/>Relancer</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty icon={Bell} title="Aucune notification" text="Les messages transactionnels apparaîtront ici après les commandes et changements de statut."/>}</div></section></>}

function Team({data,reload,can}:CommonProps){const[busy,setBusy]=useState(false);const change=async(id:string,role:string)=>{if(!window.confirm('Confirmer la modification des permissions de ce membre ?'))return;setBusy(true);const{error}=await supabase.rpc('admin_set_staff_role',{p_user_id:id,p_role:role});setBusy(false);if(error)toast.error(error.message);else{toast.success('Rôle mis à jour');await reload()}};return <><PageHead eyebrow="SÉCURITÉ" title="Équipe et permissions" text="Chaque rôle est vérifié côté serveur et appliqué par les politiques RLS Supabase."/><section className="role-grid">{[{r:'super_admin',n:'Super administrateur',d:'Accès complet et gestion des accès'},{r:'manager',n:'Gestionnaire',d:'Opérations, catalogue et commandes'},{r:'catalog_manager',n:'Catalogue',d:'Produits, prix et stocks'},{r:'order_manager',n:'Commandes',d:'Commandes et livraison'}].map(x=><article key={x.r}><ShieldCheck/><strong>{x.n}</strong><p>{x.d}</p><span>{data.staff.filter(s=>s.user_roles.some(r=>r.role===x.r)).length} membre(s)</span></article>)}</section><section className="panel table-panel"><div className="panel-head padded"><div><span className="eyebrow">MEMBRES</span><h2>Comptes de l’équipe</h2></div></div><div className="table-scroll"><table><thead><tr><th>Membre</th><th>Identifiant</th><th>État</th><th>Rôle</th><th>Depuis</th></tr></thead><tbody>{data.staff.map(s=><tr key={s.id}><td><div className="customer-cell"><span className="avatar">{s.full_name?.[0]||'B'}</span><strong>{s.full_name||'Membre BIELUMINA'}</strong></div></td><td><code>{s.id.slice(0,8)}</code></td><td><Badge tone={s.active?'success':'danger'}>{s.active?'Actif':'Révoqué'}</Badge></td><td><select disabled={busy||!can('staff.write')} value={s.user_roles[0]?.role||'viewer'} onChange={e=>change(s.id,e.target.value)}><option value="super_admin">Super administrateur</option><option value="manager">Gestionnaire</option><option value="catalog_manager">Catalogue</option><option value="order_manager">Commandes</option><option value="inventory_manager">Inventaire</option><option value="viewer">Lecture seule</option></select></td><td>{dateFr(s.created_at)}</td></tr>)}</tbody></table></div></section>{data.audit.length>0&&<section className="panel audit-panel"><div className="panel-head"><div><span className="eyebrow">TRAÇABILITÉ</span><h2>Journal des opérations sensibles</h2></div></div><div className="audit-list">{data.audit.slice(0,20).map(a=><div key={a.id}><FileClock/><span><strong>{a.action}</strong><small>{a.resource} · {a.resource_id||'global'}</small></span><time>{dateFr(a.created_at)}</time></div>)}</div></section>}</>}

function SettingsPage({data,reload}:CommonProps){const store=data.settings.find(s=>s.key==='store')?.value||{};const notif=data.settings.find(s=>s.key==='notifications')?.value||{};const[storeForm,setStoreForm]=useState({name:String(store.name||'BIELUMINA'),contact_email:String(store.contact_email||''),contact_phone:String(store.contact_phone||''),whatsapp_number:String(store.whatsapp_number||''),default_currency:String(store.default_currency||'HTG')});const[whatsapp,setWhatsapp]=useState(Boolean(notif.whatsapp_enabled));const[email,setEmail]=useState(Boolean(notif.email_enabled));const[busy,setBusy]=useState(false);const save=async(e:FormEvent)=>{e.preventDefault();setBusy(true);const[a,b]=await Promise.all([supabase.from('store_settings').update({value:{...store,...storeForm},updated_at:new Date().toISOString()}).eq('key','store'),supabase.from('store_settings').update({value:{...notif,whatsapp_enabled:whatsapp,email_enabled:email},updated_at:new Date().toISOString()}).eq('key','notifications')]);setBusy(false);const error=a.error||b.error;if(error)toast.error(error.message);else{toast.success('Paramètres enregistrés');await reload()}};return <><PageHead eyebrow="CONFIGURATION" title="Paramètres généraux" text="Les informations de contact et préférences opérationnelles de votre boutique."/><form onSubmit={save} className="settings-layout"><section className="panel form-panel"><div className="panel-head"><div><span className="eyebrow">IDENTITÉ</span><h2>Coordonnées de la boutique</h2></div></div><div className="form-grid"><label>Nom de la boutique<input value={storeForm.name} onChange={e=>setStoreForm({...storeForm,name:e.target.value})}/></label><label>Devise de référence<select value={storeForm.default_currency} onChange={e=>setStoreForm({...storeForm,default_currency:e.target.value})}><option>HTG</option><option>USD</option></select></label><label>E-mail du service client<input type="email" value={storeForm.contact_email} onChange={e=>setStoreForm({...storeForm,contact_email:e.target.value})}/></label><label>Téléphone<input value={storeForm.contact_phone} onChange={e=>setStoreForm({...storeForm,contact_phone:e.target.value})}/></label><label className="span-2">Numéro WhatsApp<input value={storeForm.whatsapp_number} onChange={e=>setStoreForm({...storeForm,whatsapp_number:e.target.value})}/></label></div></section><section className="panel form-panel"><div className="panel-head"><div><span className="eyebrow">NOTIFICATIONS</span><h2>Canaux transactionnels</h2></div></div><label className="switch-row"><span><strong>Notifications WhatsApp</strong><small>Confirmation et changements de statut</small></span><input type="checkbox" checked={whatsapp} onChange={e=>setWhatsapp(e.target.checked)}/></label><label className="switch-row"><span><strong>Secours par e-mail</strong><small>Utilisé si configuré côté serveur</small></span><input type="checkbox" checked={email} onChange={e=>setEmail(e.target.checked)}/></label><div className="info-box"><ShieldCheck/><p>Les jetons Meta et les secrets de messagerie se configurent exclusivement dans les variables d’environnement de la fonction serveur.</p></div></section><div className="settings-save"><button className="btn primary" disabled={busy}>{busy?<Loader2 className="spin"/>:<Check/>}Enregistrer les paramètres</button></div></form></>}

export default App
